const T = aide.THREE;
const CY = 0.15;
const CX = 0, CZ = -0.05;
const sunPos = new T.Vector3(CX, CY, CZ);

const sunMat = new T.MeshStandardMaterial({ color: '#ffdd33', emissive: '#ffbb00', emissiveIntensity: 1.6, roughness: 0.5 });
const sun = new T.Mesh(new T.SphereGeometry(0.06, 32, 24), sunMat);
sun.position.copy(sunPos);
aide.scene.add(sun);
const glowMat = new T.MeshBasicMaterial({ color: '#ffec9e', transparent: true, opacity: 0.22 });
const glow = new T.Mesh(new T.SphereGeometry(0.075, 32, 24), glowMat);
glow.position.copy(sunPos);
aide.scene.add(glow);
const light = new T.PointLight(0xfff2c0, 1.2, 1.5);
light.position.copy(sunPos);
aide.scene.add(light);

// planet data: name, color, size, orbitR, speed
const DEFS = [
  { name: 'Mercury', color: '#9e8e82', size: 0.009, r: 0.09, speed: 0.42 },
  { name: 'Venus', color: '#e8c47a', size: 0.014, r: 0.14, speed: 0.32 },
  { name: 'Earth', color: '#3a8de0', size: 0.015, r: 0.19, speed: 0.27 },
  { name: 'Mars', color: '#e0523a', size: 0.011, r: 0.24, speed: 0.22 },
  { name: 'Jupiter', color: '#d8a86a', size: 0.032, r: 0.32, speed: 0.15 },
  { name: 'Saturn', color: '#e6d49a', size: 0.027, r: 0.40, speed: 0.12 },
  { name: 'Uranus', color: '#8fd8d8', size: 0.019, r: 0.48, speed: 0.09 },
  { name: 'Neptune', color: '#4a6de0', size: 0.018, r: 0.55, speed: 0.07 },
];
const ringMat = new T.MeshBasicMaterial({ color: '#ffffff', transparent: true, opacity: 0.28 });
for (const d of DEFS) {
  const ring = new T.Mesh(new T.TorusGeometry(d.r, 0.0009, 6, 96), ringMat);
  ring.rotation.x = Math.PI / 2;
  ring.position.copy(sunPos);
  aide.scene.add(ring);
}
// Saturn ring
const saturnRingMat = new T.MeshBasicMaterial({ color: '#d8c890', transparent: true, opacity: 0.6, side: T.DoubleSide });

const planets = [];
DEFS.forEach((d, i) => {
  const b = aide.spawn('ball', { radius: d.size, color: d.color, position: [CX + d.r, CY, CZ] });
  const lbl = aide.spawn('label', { text: d.name, size: 0.025, position: [CX + d.r, CY + 0.045, CZ] });
  lbl.visible = false;
  let satRing = null;
  if (d.name === 'Saturn') {
    satRing = new T.Mesh(new T.TorusGeometry(d.size * 1.7, 0.0025, 6, 32), saturnRingMat);
    satRing.rotation.x = Math.PI / 2 - 0.35;
    b.add(satRing);
  }
  planets.push({ def: d, obj: b, label: lbl, angle: i * 0.8, paused: false });
});

const title = aide.spawn('label', { text: 'Solar System', size: 0.03, position: [CX, CY + 0.22, CZ - 0.05] });
const hint = aide.spawn('label', { text: 'Drag to spin - pinch planet for name', size: 0.025, position: [CX, CY + 0.175, CZ - 0.05] });

const toggle = aide.spawn('box', { size: [0.11, 0.025, 0.05], color: '#2fbf71', position: [CX, 0.03, 0.28] });
const toggleLabel = aide.spawn('label', { text: 'Pause', size: 0.025, position: [CX, 0.075, 0.28] });
const spinLabel = aide.spawn('label', { text: 'Spin: drag', size: 0.025, position: [CX - 0.18, 0.06, 0.22] });

let globalPaused = false;
let yaw = 0;
let spinVel = 0;
let dragHand = null;
let lastX = 0, lastZ = 0;
let pokeCool = 0;

aide.say('Your solar system is ready. Pinch and drag to spin it.');
aide.emit('built', { planets: 8, surface: 'plane-3' });

aide.onPinch((e) => {
  // planet pinch -> pause/resume + name
  const p = planets.find((pl) => pl.obj === e.object);
  if (p) {
    p.paused = !p.paused;
    p.label.visible = p.paused;
    aide.sound.pop();
    aide.say(p.paused ? p.name + ' paused.' : p.name + ' moving.');
    aide.emit('planet_toggled', { planet: p.def.name, paused: p.paused });
    return;
  }
  if (e.object === toggle) {
    globalPaused = !globalPaused;
    toggleLabel.setText(globalPaused ? 'Paused - poke to play' : 'Pause');
    toggle.material.color.set(globalPaused ? '#e0523a' : '#2fbf71');
    aide.sound.tick();
    return;
  }
  // empty-space pinch -> spin drag
  if (!dragHand && e.object === null) {
    dragHand = e.hand;
    lastX = e.point.x;
    lastZ = e.point.z;
    spinVel = 0;
  }
});

const tmp = new T.Vector3();
aide.onFrame((dt, t) => {
  pokeCool -= dt;
  // spin drag
  if (dragHand) {
    const h = aide.hands[dragHand];
    if (!h.visible || !h.pinching) {
      dragHand = null;
    } else {
      const dx = h.pinchPoint.x - lastX;
      const dz = h.pinchPoint.z - lastZ;
      const d = dx * 4 + dz * 2;
      yaw += d;
      spinVel = spinVel * 0.85 + (d / Math.max(dt, 0.008)) * 0.15;
      lastX = h.pinchPoint.x;
      lastZ = h.pinchPoint.z;
      if (Math.abs(spinVel) > 3) spinVel = Math.sign(spinVel) * 3;
    }
  } else if (Math.abs(spinVel) > 0.01) {
    yaw += spinVel * dt;
    spinVel *= (1 - dt * 1.2);
  }
  // open-palm flick: fast open hand over system adds spin
  for (const k of ['left', 'right']) {
    const h = aide.hands[k];
    if (h.visible && !h.pinching && k !== dragHand) {
      tmp.copy(h.palm || h.pinchPoint);
      const dx = tmp.x - CX, dz = tmp.z - CZ;
      if (Math.hypot(dx, dz) < 0.6 && Math.abs(tmp.y - CY) < 0.25) {
        const vx = h.velocity.x;
        if (Math.abs(vx) > 0.8) {
          spinVel += vx * dt * 2.5;
          if (Math.abs(spinVel) > 3) spinVel = Math.sign(spinVel) * 3;
        }
      }
    }
  }
  // poke toggle
  if (pokeCool <= 0) {
    for (const k of ['left', 'right']) {
      const h = aide.hands[k];
      if (!h.visible) continue;
      const tip = h.joints.indexTip;
      if (tip.distanceTo(toggle.position) < 0.045) {
        globalPaused = !globalPaused;
        toggleLabel.setText(globalPaused ? 'Paused - poke to play' : 'Pause');
        toggle.material.color.set(globalPaused ? '#e0523a' : '#2fbf71');
        aide.sound.tick();
        pokeCool = 0.8;
        break;
      }
    }
  }
  // advance planets
  if (!globalPaused) {
    for (const p of planets) {
      if (!p.paused) p.angle += p.def.speed * dt;
    }
    glow.scale.setScalar(1 + Math.sin(t * 2.2) * 0.04);
  }
  for (const p of planets) {
    const a = p.angle + yaw;
    const x = CX + Math.cos(a) * p.def.r;
    const z = CZ + Math.sin(a) * p.def.r;
    p.obj.position.set(x, CY, z);
    if (p.label.visible) p.label.position.set(x, CY + 0.045, z);
  }
  sun.rotation.y += dt * 0.3;
});
